args <- commandArgs(trailingOnly = TRUE)
if (length(args) != 1L) stop("Usage: Rscript integration_benchmark.R config.json")
script_file <- sub("^--file=", "", grep("^--file=", commandArgs(FALSE), value = TRUE)[1]); source(file.path(dirname(normalizePath(script_file)), "runtime.R"))
config <- read_skill_config(args[[1]])
if (!requireNamespace("Seurat", quietly = TRUE)) stop("Package 'Seurat' is required")
obj <- load_scrna_object(cfg_get(config, "input.object", required = TRUE), "auto")
sample_col <- cfg_get(config, "metadata.sample", required = TRUE); batch_col <- cfg_get(config, "metadata.batch", required = TRUE)
assert_metadata(obj, c(sample_col, batch_col))
dims <- unlist(cfg_get(config, "integration.dims", as.list(1:30)))
if (!"pca" %in% names(obj@reductions)) obj <- Seurat::NormalizeData(obj, verbose = FALSE) |> Seurat::FindVariableFeatures(verbose = FALSE) |> Seurat::ScaleData(verbose = FALSE) |> Seurat::RunPCA(verbose = FALSE)
baseline <- Seurat::FindNeighbors(obj, reduction = "pca", dims = dims, graph.name = c("baseline_nn", "baseline_snn"), verbose = FALSE)
baseline <- Seurat::FindClusters(baseline, graph.name = "baseline_snn", resolution = cfg_get(config, "integration.resolution", 0.5), cluster.name = "baseline_clusters", verbose = FALSE)
baseline <- Seurat::RunUMAP(baseline, reduction = "pca", dims = dims, reduction.name = "umap_baseline", verbose = FALSE)
methods <- unlist(cfg_get(config, "integration.methods", list("none")))
records <- data.frame(method = "none", reduction = "pca", status = "completed", notes = "required uncorrected baseline")
if ("harmony" %in% methods) {
  if (!requireNamespace("harmony", quietly = TRUE)) stop("Harmony requested but package 'harmony' is unavailable")
  baseline <- harmony::RunHarmony(baseline, group.by.vars = batch_col, reduction = "pca", reduction.save = "harmony", verbose = FALSE)
  baseline <- Seurat::RunUMAP(baseline, reduction = "harmony", dims = dims, reduction.name = "umap_harmony", verbose = FALSE)
  records <- rbind(records, data.frame(method = "harmony", reduction = "harmony", status = "completed", notes = "evaluate biological conservation separately"))
}
out <- prepare_output(config); table_path <- file.path(out, "integration_methods.tsv"); object_path <- file.path(out, "integration_benchmark_object.qs")
utils::write.table(records, table_path, sep = "\t", quote = FALSE, row.names = FALSE); save_scrna_object(baseline, object_path)
plot_path <- file.path(out, "integration_diagnostics.pdf"); grDevices::pdf(plot_path, width = 9, height = 7); print(Seurat::DimPlot(baseline, reduction = "umap_baseline", group.by = batch_col)); if ("umap_harmony" %in% names(baseline@reductions)) print(Seurat::DimPlot(baseline, reduction = "umap_harmony", group.by = batch_col)); grDevices::dev.off()
write_run_manifest(config, "benchmark-scrna-integration", out, c(table_path, object_path, plot_path), "No method was declared best automatically")
